import React from 'react';

import Printer from '@pohodnik/icons/svg/Devices/Printer';
import clsx from 'clsx';
import { QRCodeSVG } from 'qrcode.react';

import PohodnikChevron from '@apps/Print/components/PohodnikChevron';
import A4Page from '@components/A4Page';
import Logo from '@components/Logo';
import PageLoader from '@components/PageLoader';
import { getDomain } from '@helpers/domain.helper';
import { handleApiError } from '@helpers/httpClient';
import { err } from '@helpers/notificationHelper';
import PohAva from '@ui-kit/Ava';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohContainer from '@ui-kit/layout/Container';

import style from './style.module.less';
import {
  obstacleCategoryNameResource,
  obstacleTypeNameResourceRP,
} from '../../../Obstacles/@resources/obstacles.resource';
import { ObstacleType } from '../../../Obstacles/@types/obstacles.types';
import { getRouteThreadItems } from '../../../Routes/@helpers/route.helper';
import { getRouteObjectsAsync } from '../../../Routes/@services/routes.service';
import {
  IBaseRouteObjectPoint,
  IRouteObject,
  RouteObjectType,
} from '../../../Routes/@types/routes.types';
import { getHikingDataAsync } from '../../@services/hiking.service';
import { IHikingData } from '../../@types/hiking.types';

interface IHikingObstacleNotesProps {
  id_hiking: number;
}

const HikingObstacleNotes: React.FC<IHikingObstacleNotesProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [routeObjects, setRouteObjects] = React.useState<IRouteObject[] | null>(null);
  const [isIncludeNotInDistance, setIsIncludeNotInDistance] = React.useState(false);

  React.useEffect(() => {
    getHikingDataAsync(id_hiking)
      .then<IHikingData>(handleApiError)
      .then((data) => {
        setHikingData(data);
        data.route.id && getRouteObjectsAsync(data.route.id).then(setRouteObjects).catch(err);
      })
      .catch(err);
  }, [id_hiking]);

  if (hikingData == null || routeObjects == null) {
    return <PageLoader />;
  }

  const pointsInDistance = routeObjects.filter(
    (mo) => mo.type === RouteObjectType.Point && (mo.is_in_distance || isIncludeNotInDistance),
  ) as IBaseRouteObjectPoint[];
  const pointsWithObstacles = pointsInDistance.filter((p) => p.obstacle);

  const routeThread = getRouteThreadItems(routeObjects).join(' — ');

  return (
    <PohContainer>
      <header className="d-print-none">
        <Breadcrumb
          data={[
            { href: '/hiking', text: 'Походы' },
            { href: `/hiking/${id_hiking}`, text: hikingData.name },
            { href: `/hiking/${id_hiking}/notes`, text: 'Записки', active: true },
          ]}
        />
        <header className="mb-3 d-flex align-items-center">
          <h3>Записки для похода «{hikingData.name}»</h3>
          <aside className="ms-auto d-flex align-items-center">
            <PohCheckbox
              checked={isIncludeNotInDistance}
              onChange={setIsIncludeNotInDistance}
              label="Не в дистанции"
            />
            <PohButton icon onClick={() => window.print()} className="ms-3">
              <Printer />
            </PohButton>
          </aside>
        </header>
      </header>
      <A4Page>
        {pointsWithObstacles.map((routeObject) => {
          if (!routeObject.obstacle) return '';
          const { obstacle } = routeObject;

          const link = `https://${getDomain()}/hiking/${id_hiking}/obstacles/${obstacle.id}?source=qr`;

          return (
            <>
              <hr />
              <table className={clsx('table table-bordered', style.subpage)}>
                <tr>
                  <td width="50%">
                    <section className="d-flex justify-content-between flex-column h-100">
                      <div className="d-flex justify-content-between">
                        <Logo />
                      </div>
                      <header className="text-center">
                        <PohodnikChevron
                          header={hikingData.name}
                          subheader="Походники Пензы"
                          url={hikingData.visual.photo}
                          style={{ width: 180 }}
                        />
                        <h3>
                          {obstacle.type === ObstacleType.Pass && 'Перевальная записка'}
                          {obstacle.type === ObstacleType.Peak && 'Вершинная записка'}
                          {obstacle.type === ObstacleType.Poi &&
                            'Записка о посещении точки интереса (POI)'}
                        </h3>
                        <h5>
                          {obstacle.name}{' '}
                          {`(${obstacleCategoryNameResource[obstacle.category]}, ${obstacle.altitude})`}
                        </h5>
                      </header>

                      <div className="text-start d-flex justify-content-between align-items-center">
                        <p>
                          <div className="mb-2">
                            <small>
                              Подробная информация о походе:
                              <br />
                              <big>
                                <code>{`https://${getDomain()}/hiking/${id_hiking}`}</code>
                              </big>
                            </small>
                          </div>
                          <small>
                            Присоединяйтесь к нашим группам в соц.сетях:
                            <br />
                            <big>
                              <code>https://${getDomain()}/contacts</code>
                            </big>
                          </small>
                        </p>
                        <QRCodeSVG
                          value={link}
                          width={80}
                          height={80}
                          onClick={() => window.open(link)}
                        />
                      </div>
                    </section>
                  </td>
                  <td>
                    <div className="d-flex flex-column justify-content-between h-100 overflow-hidden">
                      <section>
                        <p>
                          Группа туристов из <b>г. Пенза</b>{' '}
                          <em>
                            <b>«Походники&nbsp;Пензы»</b>
                          </em>
                          <br />c <small>{new Date(hikingData?.start).toLocaleDateString()}</small>
                          &nbsp;по{' '}
                          <small>{new Date(hikingData?.finish).toLocaleDateString()}</small>{' '}
                          совершающая <b>{hikingData.type.name}</b> поход по маршруту:
                          <em className="d-block pY-1">
                            <small>{routeThread}</small>
                          </em>
                          вышла на {obstacleTypeNameResourceRP[obstacle.type]}{' '}
                          <b>{`${obstacle.name} (${obstacleCategoryNameResource[obstacle.category]}, ${obstacle.altitude})`}</b>{' '}
                          в ____:____
                          <div className="pt-1">
                            Дата ____.____.20____ г. cо стороны _______________________
                          </div>
                        </p>
                        <p>
                          <div className="d-flex justify-content-between">
                            <div>Группа ({hikingData.hikers.length} чел.):</div>
                          </div>
                          <div className="my-2 d-flex flex-wrap">
                            {hikingData.hikers
                              .sort((a, b) => a.positions?.[0]?.id - b.positions?.[0]?.id)
                              .map((hiker) => (
                                <div
                                  key={hiker.idUser}
                                  style={{ lineHeight: '1em' }}
                                  className="my-2 mb-2 w-50"
                                >
                                  <PohAva
                                    alt={[hiker.surname, hiker.name].join('\u00a0')}
                                    className="me-2 float-start"
                                    src={hiker.photo['50']}
                                  />
                                  <strong>{[hiker.surname, hiker.name].join('\u00a0')}</strong>
                                  <br />
                                  <small>{hiker.positions.map((p) => p.name).join(', ')}</small>
                                </div>
                              ))}
                          </div>
                        </p>
                      </section>
                      <section>
                        <div className="border-bottom">&nbsp;</div>
                        <div className="border-bottom">&nbsp;</div>
                        <div className="border-bottom">&nbsp;</div>
                        <div className="border-bottom">&nbsp;</div>
                        <div className="border-bottom">&nbsp;</div>
                        <div className="border-bottom">&nbsp;</div>
                        <div className="border-bottom">&nbsp;</div>
                      </section>
                    </div>
                  </td>
                </tr>
              </table>
            </>
          );
        })}
      </A4Page>
    </PohContainer>
  );
};

export default HikingObstacleNotes;
